import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.B5WAEDB7.js";const o="/screenshots/en/erste-schritte/oberflaeche/space-navigation.png",n="/screenshots/en/erste-schritte/oberflaeche/grid-bereich.png",i="/screenshots/en/erste-schritte/oberflaeche/grid-werkzeugleiste.png",b=JSON.parse('{"title":"The interface at a glance","description":"The layout of the ApptiveGrid interface — sidebar, Space areas, view switching, and settings.","frontmatter":{"title":"The interface at a glance","description":"The layout of the ApptiveGrid interface — sidebar, Space areas, view switching, and settings."},"headers":[],"relativePath":"en/erste-schritte/oberflaeche.md","filePath":"en/erste-schritte/oberflaeche.md","lastUpdated":1787319236000}'),l={name:"en/erste-schritte/oberflaeche.md"};function d(h,e,c,p,g,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="the-interface-at-a-glance" tabindex="-1">The interface at a glance <a class="header-anchor" href="#the-interface-at-a-glance" aria-label="Permalink to &quot;The interface at a glance&quot;">​</a></h1><p>ApptiveGrid is consistently split in two: a <strong>sidebar</strong> on the left for navigation, and the <strong>content area</strong> on the right. What appears in the sidebar depends on where you are.</p><h2 id="the-space-overview" tabindex="-1">The Space overview <a class="header-anchor" href="#the-space-overview" aria-label="Permalink to &quot;The Space overview&quot;">​</a></h2><p>After signing in, you land on the overview of all Spaces.</p><p>Here you&#39;ll find:</p><table tabindex="0"><thead><tr><th>Element</th><th>Function</th></tr></thead><tbody><tr><td><strong>All Spaces</strong></td><td>All Spaces you have access to</td></tr><tr><td><strong>Shared with me</strong></td><td>Only Spaces others have shared with you</td></tr><tr><td><strong>Create new Space</strong></td><td>Creates an empty Space</td></tr><tr><td><strong>Search Space</strong></td><td>Filters the list by name</td></tr><tr><td><strong>Group by category</strong></td><td>Bundles Spaces by an assigned category</td></tr></tbody></table><p>Below that, templates appear under the heading <em>Or start with a template</em>.</p><p>If you don&#39;t have a Space yet, you&#39;ll see the prompt <em>Create your first Space</em> instead.</p><h2 id="inside-a-space" tabindex="-1">Inside a Space <a class="header-anchor" href="#inside-a-space" aria-label="Permalink to &quot;Inside a Space&quot;">​</a></h2><p>Open a Space, and the sidebar switches to the Space navigation. It&#39;s organized into three areas:</p><p><img src="'+o+'" alt="The sidebar inside a Space with the Grids, Pages, and Flows areas"></p><h3 id="grids" tabindex="-1">Grids <a class="header-anchor" href="#grids" aria-label="Permalink to &quot;Grids&quot;">​</a></h3><p>Your data tables. Under each Grid are two groups:</p><ul><li><strong>Views</strong> — every representation of this Grid</li><li><strong>Forms</strong> — every input mask of this Grid</li></ul><p>Use <strong>Create</strong> to add a new View or Form.</p><div class="tip custom-block"><p class="custom-block-title">Long Grid lists</p><p>By default, the navigation shows the first <strong>10</strong> Grids; the rest are collapsed behind <em>Show more</em>. You can change this number in the <a href="/en/spaces/navigation">Space settings</a>.</p></div><h3 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h3><p>All Pages of the Space, whether you use them as a Portal or as internal documentation.</p><h3 id="flows" tabindex="-1">Flows <a class="header-anchor" href="#flows" aria-label="Permalink to &quot;Flows&quot;">​</a></h3><p>All automations of the Space.</p><div class="tip custom-block"><p class="custom-block-title">Adjusting the order</p><p>Whether <strong>Grids before Pages</strong> or <strong>Pages before Grids</strong> appear is set in the Space settings. If your team mainly works with portals, <em>Pages before Grids</em> is usually more practical.</p></div><h2 id="the-grid-area" tabindex="-1">The Grid area <a class="header-anchor" href="#the-grid-area" aria-label="Permalink to &quot;The Grid area&quot;">​</a></h2><p>Open a Grid, and you always see a specific <strong>View</strong> of it — never the Grid itself. Use the sidebar to switch between Views.</p><p><img src="'+n+'" alt="The Grid area with sidebar, toolbar, and table"></p><p>The toolbar above the table contains:</p><p><img src="'+i+'" alt="The toolbar above the table"></p><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Filter</strong></td><td>Determines which Entries are visible</td></tr><tr><td><strong>Sort</strong></td><td>Determines the order</td></tr><tr><td><strong>Group</strong></td><td>Bundles Entries by a field</td></tr><tr><td><strong>Hidden</strong></td><td>Hides and shows columns</td></tr><tr><td><strong>Search</strong></td><td>Searches Entries</td></tr><tr><td><strong>Share</strong></td><td>Generates a link or QR code to the View</td></tr><tr><td><strong>More</strong> (⋮)</td><td>CSV export, duplicate, reorder columns, edit empty state</td></tr></tbody></table><p>Clicking a row opens the Entry in detail view.</p><div class="warning custom-block"><p class="custom-block-title">If a button is missing</p><p>ApptiveGrid hides features you don&#39;t have permission for — no error message appears. If an expected button is missing, check your Role in the Space. See <a href="/en/fehlerbehebung/fehlende-schaltflaechen">I can&#39;t find a button</a>.</p></div><h2 id="the-form-area" tabindex="-1">The Form area <a class="header-anchor" href="#the-form-area" aria-label="Permalink to &quot;The Form area&quot;">​</a></h2><p>The Form editor has three tabs:</p><ul><li><strong>Pages</strong> — arrange fields and text blocks, manage form pages</li><li><strong>Layout</strong> — colors, logo, background image, field style</li><li><strong>More</strong> — save for later, automatic submission, multiple languages</li></ul><p>On the left are the fields not yet used, under <em>Available fields</em>. On the right, a preview of the Form builds up.</p><h2 id="the-page-area" tabindex="-1">The Page area <a class="header-anchor" href="#the-page-area" aria-label="Permalink to &quot;The Page area&quot;">​</a></h2><p>The Page editor works like a text document: you start typing, and pressing the <strong>spacebar</strong> opens the block picker. The placeholder text reads <em>Start typing or press space to open the block menu</em>.</p><p>Use <em>Show structure mode</em> to reveal two additional panels:</p><ul><li><strong>Page structure</strong> — the block tree, for reordering and nested layouts</li><li><strong>Block settings</strong> — the settings of the selected block</li></ul><p>A Page has two modes: <strong>Editor</strong> for editing and <strong>Application</strong> for previewing it the way visitors see it.</p><h2 id="the-flow-area" tabindex="-1">The Flow area <a class="header-anchor" href="#the-flow-area" aria-label="Permalink to &quot;The Flow area&quot;">​</a></h2><p>The Flow editor is a canvas of nodes and connections.</p><ul><li>On the left, you pick new steps, split into <strong>Triggers</strong>, <strong>Actions</strong>, and <strong>Helpers</strong>.</li><li>Clicking a step opens its settings.</li><li>The <em>Center on all nodes</em>, <em>Auto-arrange nodes</em>, and <em>Toggle minimap</em> tools help with large Flows.</li></ul><p>The <strong>History</strong> tab shows past Runs with start time, duration, number of steps, and status.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>There are two separate settings areas — a common source of confusion:</p><h3 id="account-settings" tabindex="-1">Account settings <a class="header-anchor" href="#account-settings" aria-label="Permalink to &quot;Account settings&quot;">​</a></h3><p>Apply to <strong>you personally</strong>, via <em>Profile &amp; settings</em>:</p><ul><li><strong>Profile</strong> — name, profile picture, delete account</li><li><strong>Billing</strong> — plan and invoicing</li><li><strong>API Credentials</strong> — keys for accessing the programming interface</li></ul><h3 id="space-settings" tabindex="-1">Space settings <a class="header-anchor" href="#space-settings" aria-label="Permalink to &quot;Space settings&quot;">​</a></h3><p>Apply to <strong>one Space</strong>:</p><ul><li><strong>General</strong> — plan, seats, Space identifier, navigation order</li><li><strong>Webhooks</strong> — outgoing notifications to other systems</li><li><strong>Links</strong> — overview of all external links of this Space</li></ul><h2 id="cross-cutting-elements" tabindex="-1">Cross-cutting elements <a class="header-anchor" href="#cross-cutting-elements" aria-label="Permalink to &quot;Cross-cutting elements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Function</th></tr></thead><tbody><tr><td><strong>Search</strong></td><td>Searches Entries</td></tr><tr><td><strong>Help menu</strong></td><td>Access to help and what&#39;s new</td></tr><tr><td><strong>Chat</strong></td><td>Direct contact with support</td></tr><tr><td><strong>Fullscreen</strong></td><td>Hides the sidebar</td></tr><tr><td><strong>Change notice</strong></td><td>Reports when other people have changed the Grid</td></tr></tbody></table><p>When a new app version is deployed, a notice appears asking you to reload the page.</p>',53)])])}const f=t(l,[["render",d]]);export{b as __pageData,f as default};
